import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

export default function AdminDashboard() {
  const navigate = useNavigate();
  const { logout } = useContext(AuthContext);

  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [results, setResults] = useState({});
  const [reportHash, setReportHash] = useState("");

  useEffect(() => {
    fetchData();
  }, []);

  async function fetchData() {
    try {
      const [stateRes, usersRes, candRes, logsRes, resultsRes] = await Promise.all([
        api.get("/admin/voting-state"),
        api.get("/admin/pending-users"),
        api.get("/admin/candidates"),
        api.get("/admin/logs"),
        api.get("/admin/results"),
      ]);
      setVotingOpen(stateRes.data.votingOpen);
      setPendingUsers(usersRes.data);
      setCandidates(candRes.data);
      setLogs(logsRes.data);
      setResults(resultsRes.data);
    } catch (err) {
      console.error("Dashboard fetch error:", err);
    }
  }

  async function toggleVoting() {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error("Toggle voting failed:", err);
    }
  }

  async function approveUser(id) {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchData();
    } catch (err) {
      console.error("Approve user failed:", err);
    }
  }

  async function rejectUser(id) {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchData();
    } catch (err) {
      console.error("Reject user failed:", err);
    }
  }

  async function deleteCandidate(id) {
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchData();
    } catch (err) {
      console.error("Delete candidate failed:", err);
    }
  }

  async function generateReport() {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      console.error("Generate report failed:", err);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900">
      {/* Header */}
      <header className="flex items-center justify-between bg-white shadow px-6 py-4">
        <h1 className="text-2xl font-bold text-blue-600">iVote Admin Dashboard</h1>
        <Button variant="destructive" onClick={logout}>
          Logout
        </Button>
      </header>

      {/* Content */}
      <main className="p-6 grid gap-6 lg:grid-cols-2">
        {/* Voting Status */}
        <Card>
          <CardHeader>
            <CardTitle>Voting Status</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="mb-3 text-lg font-medium">
              Current status:{" "}
              <span className={votingOpen ? "text-green-600" : "text-red-600"}>
                {votingOpen ? "Open" : "Closed"}
              </span>
            </p>
            <Button onClick={toggleVoting}>
              {votingOpen ? "Close Voting" : "Open Voting"}
            </Button>
          </CardContent>
        </Card>

        {/* Pending Users */}
        <Card>
          <CardHeader>
            <CardTitle>Pending Voter Registrations</CardTitle>
          </CardHeader>
          <CardContent>
            {pendingUsers.length === 0 ? (
              <p className="text-gray-500">No pending users</p>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Student No.</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Email</TableHead>
                    <TableHead>Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {pendingUsers.map((u) => (
                    <TableRow key={u.id}>
                      <TableCell>{u.studentNumber}</TableCell>
                      <TableCell>{u.name}</TableCell>
                      <TableCell>{u.email}</TableCell>
                      <TableCell>
                        <div className="flex gap-2">
                          <Button size="sm" onClick={() => approveUser(u.id)}>Approve</Button>
                          <Button size="sm" variant="destructive" onClick={() => rejectUser(u.id)}>Reject</Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>

        {/* Candidates */}
        <Card>
          <CardHeader>
            <CardTitle>Candidates</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  <TableHead>Position</TableHead>
                  <TableHead>Party</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {candidates.map((c) => (
                  <TableRow key={c.id}>
                    <TableCell>{c.name}</TableCell>
                    <TableCell>{c.position}</TableCell>
                    <TableCell>{c.party || "-"}</TableCell>
                    <TableCell>
                      <Button size="sm" variant="destructive" onClick={() => deleteCandidate(c.id)}>
                        Delete
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        {/* System Logs */}
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>System Logs</CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="divide-y divide-gray-200">
              {logs.map((log) => (
                <li key={log.id} className="py-2 text-sm">
                  <span className="font-medium">{log.action}</span>{" "}
                  <span className="text-gray-500">
                    {new Date(log.createdAt).toLocaleString()}
                  </span>
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>

        {/* Results */}
        <Card>
          <CardHeader>
            <CardTitle>Election Results</CardTitle>
          </CardHeader>
          <CardContent>
            {Object.keys(results.positionResults || {}).map((pos) => (
              <div key={pos} className="mb-4">
                <h3 className="font-semibold">{pos}</h3>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Name</TableHead>
                      <TableHead>Party</TableHead>
                      <TableHead>Votes</TableHead>
                      <TableHead>Status</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {results.positionResults[pos].map((c) => (
                      <TableRow key={c.id}>
                        <TableCell>{c.name}</TableCell>
                        <TableCell>{c.party || "-"}</TableCell>
                        <TableCell>{c.votes}</TableCell>
                        <TableCell>
                          {results.winners[pos]?.id === c.id ? (
                            <span className="text-green-600 font-semibold">Winner</span>
                          ) : (
                            "—"
                          )}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            ))}
          </CardContent>
        </Card>

        {/* Reports */}
        <Card>
          <CardHeader>
            <CardTitle>Reports</CardTitle>
          </CardHeader>
          <CardContent>
            <Button onClick={generateReport}>Generate Final Report</Button>
            {reportHash && (
              <p className="mt-2 text-sm text-gray-600">
                Cryptographic Hash: <span className="font-mono">{reportHash}</span>
              </p>
            )}
          </CardContent>
        </Card>
      </main>
    </div>
  );
}
